script:
frappe.ui.form.on("Payment Request", {
	refresh(frm) {
		if (frm.is_new() || frm.doc.docstatus !== 0) {
			return;
		}

		frm.add_custom_button(
			__("Copy approval link"),
			() => {
				const path = `/app/payment-request/${encodeURIComponent(frm.doc.name)}`;
				const url = `${window.location.origin}${path}`;
				frappe.utils.copy_to_clipboard(url);
				frappe.show_alert({
					message: __(
						"Link copied. Send to the next approver via IM (login and approver role required)."
					),
					indicator: "green",
				});
			},
			__("Share")
		);
	},
});
